def _normalize_canonical_parcel(parcel: dict, index: int) -> tuple[dict, bool]:
    parcel_ref = parcel.get("parcel_ref") or {}
    operations = parcel.get("operations") or {}
    fertilizer = operations.get("fertilizer") or {}
    constraints = parcel.get("constraints") or {}
    biodiversity_area = constraints.get("biodiversity_area") or {}
    crop = parcel.get("crop") or {}

    explicit_parcel_id = parcel.get("parcel_id")
    if explicit_parcel_id:
        # An explicitly authored `parcel_id` (synthetic/canonical fixtures)
        # is a real identity value, never an index fallback.
        parcel_id, identity_is_stable = explicit_parcel_id, True
    else:
        parcel_id, identity_is_stable = _resolve_parcel_identity(parcel_ref, index)

    return {
        "parcel_id": parcel_id,
        "area_ha": parcel.get("area_ha"),
        "land_use": parcel.get("land_use"),
        "slope_percent": parcel.get("slope_percent"),
        "raw_label": parcel.get("raw_label") or crop.get("crop_name"),
        "operations": {
            "psm_used": operations.get("psm_used"),
            "cutting_dates": operations.get("cutting_dates"),
            "fertilizer": {
                "mineral_n_kg_per_ha": fertilizer.get("mineral_n_kg_per_ha"),
                "organic_n_kg_per_ha": fertilizer.get("organic_n_kg_per_ha"),
            },
        },
        "is_biodiversity_area": biodiversity_area.get("is_biodiversity_area"),
        "is_nonproductive_area": parcel.get("is_nonproductive_area"),
        "is_agroforestry_strip": parcel.get("is_agroforestry_strip"),
    }, identity_is_stable


def build_land_parcels_with_identity(payload: dict) -> list[tuple[dict, bool]]:
    """Return the exact same `land.parcels` list `adapt_payload_for_measures()`
    sends to OPA, paired per-parcel with whether its `parcel_id` is a stable
    identity (Issue #96). Single source of truth for "what are this farm/
    year's canonical parcels and their parcel_ids" -- `adapt_payload_for_
    measures()` below discards the stability flag before building the

def adapt_payload_for_measures(payload: dict) -> dict:
    farm = payload.get("farm") or {}
    land = payload.get("land") or {}
    canonical_aggregate = land.get("aggregate") or {}
    farm_certifications = farm.get("certifications") or {}
    organic = farm_certifications.get("organic") or {}
    farm_region = farm.get("region") or {}
    documentation = payload.get("documentation") or {}
    oepul = payload.get("oepul") or {}
    oepul_shared = oepul.get("shared") or {}
    oepul_measures = oepul.get("measures") or {}
    o6_13 = oepul_measures.get("o6_13") or {}
    o6_15 = oepul_measures.get("o6_15") or {}
    ama_additional = payload.get("ama_additional") or {}
    additional_land = ama_additional.get("land") or {}
    fsl = additional_land.get("fsl") or {}
    aggregate = fsl.get("aggregate") or {}

    # An existing canonical `null` at land.aggregate.nitrogen_input_kg_per_ha must not
    # suppress a valid supplemental fallback from the ama_additional-derived aggregate:
    # dict.get(key, default) only falls back when the key is *absent*, not when its
    # value is present-but-null, so the null-check has to be explicit here.
    canonical_nitrogen_input = canonical_aggregate.get("nitrogen_input_kg_per_ha")
    nitrogen_input_kg_per_ha = (
        canonical_nitrogen_input
        if canonical_nitrogen_input is not None
        else aggregate.get("nitrogen_input_kg_per_ha")
    )

    # The identity-stability flag is deliberately discarded here: it is a
    # read-only concern of the parcel-overlay identity API
    # (`api.parcel_inputs`), never a field OPA's own input contract gains.
    parcels: list[dict] = [item for item, _identity_is_stable in build_land_parcels_with_identity(payload)]

    return {
        "farm": {
            "farm_id": farm.get("farm_id"),
            "year": farm.get("year"),
            "region": {
                "is_protected_area": farm_region.get("is_protected_area"),
            },
            "certifications": {
                "organic": {
                    "is_certified": organic.get("is_certified"),
                }
            },
        },
        "land": {
            "total_area_ha": land.get("total_area_ha"),
            "arable_area_ha": land.get("arable_area_ha"),
            "grassland_area_ha": land.get("grassland_area_ha"),
            "special_crops_area_ha": land.get(
                "special_crops_area_ha",
                aggregate.get("schlagnutzungsart_spezialkultur_flaeche_ha"),
            ),
            "alpine_pasture_area_ha": land.get("alpine_pasture_area_ha"),
            "parcels": parcels,
            "aggregate": {
                "begruenungsflaeche_ha": aggregate.get("begruenungsflaeche_ha"),
                "existing_biodiversity_area_ha": aggregate.get("existing_biodiversity_area_ha"),
                "nitrogen_input_kg_per_ha": nitrogen_input_kg_per_ha,
                "tillage_type": aggregate.get("tillage_type"),
                "soil_cover": aggregate.get("soil_cover"),
                "mulchsaat_technology_available": aggregate.get("mulchsaat_technology_available"),
            },
        },
        "livestock": {
            "species_groups": _copy_species_groups(payload),
        },
        "documentation": {
            "nutrient_balance_complete": documentation.get("nutrient_balance_complete"),
        },
        "oepul": {
            "shared": {
                "parcels": oepul_shared.get("parcels") or [],
                "livestock_events": oepul_shared.get("livestock_events") or [],
            },
            "measures": {
                "o6_13": {
                    "protected_cultivation_area_ha": o6_13.get("protected_cultivation_area_ha"),
                    "parcels": o6_13.get("parcels") or [],
                    "beneficials": o6_13.get("beneficials") or [],
                },
                "o6_15": {
                    "behirtung_days": o6_15.get("behirtung_days"),
                },
            },
        },
    }


